Object.assign(SNIP,{});PRESET_NOTES["l10"]={"Ví dụ: Cộng đoạn bằng mảng hiệu": "Ba lần cập nhật chỉ sửa sáu ô của d. Vòng lặp cuối cộng dồn d để dựng a. Bật Đoán trước để đoán ô nào của d bị trừ.", "Ví dụ: Lúc nào đông người nhất?": "Mỗi khách: +1 ở giờ vào, −1 ngay sau giờ ra. Khi quét, cur là số người có mặt tại giờ t. Đông nhất là 3 người lúc 4 giờ.", "Ví dụ: Cộng dồn hai lần để hỏi tổng đoạn": "Cộng dồn lần một: từ d ra a. Cộng dồn lần hai: từ a ra pre. Sau đó mỗi câu hỏi tổng đoạn vẫn O(1). a = 3 5 5 2 2 2, tổng a[2..4] = 9.", "Lỗi: mảng hiệu thiếu một ô": "Khi đoạn cập nhật kết thúc ở phần tử cuối, r + 1 = n. Mảng hiệu phải có n + 1 ô. Trình mô phỏng dừng và chỉ ra chỉ số vượt quá."};EX_HINTS["l10"]=[["Chỉ số từ 1 nên mảng hiệu cần các ô 1..n+1: khai báo d[100002].", "Tổng các cập nhật tại một ô có thể tới 10⁹: dùng long long cho an toàn."], ["Thời điểm tới 10⁵ và b + 1 có thể bằng 10⁵ + 1: mảng cần 100002 ô, khai báo toàn cục.", "Chỉ cập nhật khi cur > best (lớn hơn hẳn) để giữ thời điểm sớm nhất."], ["Đèn ở cuối đang bật khi và chỉ khi nó bị đảo một số lẻ lần.", "Đếm số lần bị đảo của mỗi đèn bằng mảng hiệu, rồi đếm các ô lẻ."]];
