RACE_X["race-a10"]=Object.assign(RACE_X["race-a10"]||{},{cs:["using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), q = int.Parse(t[1]);\n        long[] a = new long[n + 1];\n        for (int k = 0; k < q; k++)\n        {\n            int[] c = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            for (int i = c[0]; i <= c[1]; i++) a[i] += c[2];\n        }\n        long s = 0;\n        foreach (long x in a) s += x;\n        Console.WriteLine(s);\n    }\n}", "using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), q = int.Parse(t[1]);\n        long[] d = new long[n + 2];\n        for (int k = 0; k < q; k++)\n        {\n            int[] c = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            d[c[0]] += c[2];\n            d[c[1] + 1] -= c[2];\n        }\n        long s = 0, cur = 0;\n        for (int i = 1; i <= n; i++)\n        {\n            cur += d[i];\n            s += cur;\n        }\n        Console.WriteLine(s);\n    }\n}"]});
RACE_X["race-a10"]=Object.assign(RACE_X["race-a10"]||{},{py:["n, q = map(int, input().split())\na = [0] * (n + 1)\nfor _ in range(q):\n    l, r, v = map(int, input().split())\n    for i in range(l, r + 1):\n        a[i] += v\nprint(sum(a))", "n, q = map(int, input().split())\nd = [0] * (n + 2)\nfor _ in range(q):\n    l, r, v = map(int, input().split())\n    d[l] += v\n    d[r + 1] -= v\ns = 0\ncur = 0\nfor i in range(1, n + 1):\n    cur += d[i]\n    s += cur\nprint(s)"]});
makeStepRace(document.getElementById("race-a10"),{variants:[{label:"Cộng vào từng ô của đoạn: O(n · q)",code:"#include <iostream>\nusing namespace std;\n\nint a[100001];\n\nint main() {\n    int n, q;\n    cin >> n >> q;\n    while (q--) {\n        int l, r, v;\n        cin >> l >> r >> v;\n        for (int i = l; i <= r; i++) a[i] += v;\n    }\n    long long s = 0;\n    for (int i = 1; i <= n; i++) s += a[i];\n    cout << s << \"\\n\";\n    return 0;\n}"},{label:"Mảng hiệu: O(n + q)",code:"#include <iostream>\nusing namespace std;\n\nint d[100002];\n\nint main() {\n    int n, q;\n    cin >> n >> q;\n    while (q--) {\n        int l, r, v;\n        cin >> l >> r >> v;\n        d[l] += v;\n        d[r + 1] -= v;\n    }\n    long long s = 0, cur = 0;\n    for (int i = 1; i <= n; i++) {\n        cur += d[i];\n        s += cur;\n    }\n    cout << s << \"\\n\";\n    return 0;\n}"}],gen:n=>n+" "+n+"\n"+Array.from({length:n},(_,i)=>{const l=1+(i*13)%n,r=Math.min(n,l+(n>>1));return l+" "+r+" 1"}).join("\n"),ns:[50,100,200,400],note:"q = n lần cập nhật, mỗi đoạn dài khoảng n/2. Với mảng hiệu, mỗi lần cập nhật chỉ sửa hai ô."});
const PR10=[{label:"Ví dụ: Cộng đoạn bằng mảng hiệu",input:"3\n2 4 5\n0 3 1\n5 6 2",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 7;\n    vector<int> d(n + 1, 0);\n    int q;\n    cin >> q;\n    while (q--) {\n        int l, r, v;\n        cin >> l >> r >> v;\n        d[l] += v;\n        d[r + 1] -= v;\n    }\n    vector<int> a(n, 0);\n    int cur = 0;\n    for (int i = 0; i < n; i++) {\n        cur += d[i];\n        a[i] = cur;\n    }\n    for (int x : a) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"d",ptr:["l","r+1"],label:"d (mảng hiệu)"},{type:"cells",of:"a",ptr:["i"],label:"a (dựng lại)"},{type:"vars",names:["cur"]}],predict:[{line:14,v:"r+1",q:"Ô nào của d sẽ bị trừ v? (bấm vào ô trong hàng d)"}],py:{code:"n = 7\nd = [0] * (n + 1)\nq = int(input())\nfor _ in range(q):\n    l, r, v = map(int, input().split())\n    d[l] += v\n    d[r + 1] -= v\na = [0] * n\ncur = 0\nfor i in range(n):\n    cur += d[i]\n    a[i] = cur\nprint(*a)",predict:[{line:7,v:"r+1",q:"Ô nào của d sẽ bị trừ v? (bấm vào ô trong hàng d)"}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 7;\n        int[] d = new int[n + 1];\n        int q = int.Parse(Console.ReadLine());\n        for (int k = 0; k < q; k++)\n        {\n            string[] t = Console.ReadLine().Split();\n            int l = int.Parse(t[0]), r = int.Parse(t[1]), v = int.Parse(t[2]);\n            d[l] += v;\n            d[r + 1] -= v;\n        }\n        int[] a = new int[n];\n        int cur = 0;\n        for (int i = 0; i < n; i++)\n        {\n            cur += d[i];\n            a[i] = cur;\n        }\n        Console.WriteLine(string.Join(\" \", a));\n    }\n}",predict:[{line:15,v:"r+1",q:"Ô nào của d sẽ bị trừ v? (bấm vào ô trong hàng d)"}]}},{label:"Ví dụ: Lúc nào đông người nhất?",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    // 5 khách, giờ vào và giờ ra (có mặt cả hai giờ đó), giờ từ 0 đến 11\n    int vao[5] = {1, 2, 4, 6, 7};\n    int ra[5]  = {4, 5, 6, 9, 8};\n    vector<int> d(13, 0);\n    for (int k = 0; k < 5; k++) {\n        d[vao[k]]++;\n        d[ra[k] + 1]--;\n    }\n    int cur = 0, dongNhat = 0, gio = 0;\n    for (int t = 0; t < 12; t++) {\n        cur += d[t];\n        if (cur > dongNhat) {\n            dongNhat = cur;\n            gio = t;\n        }\n    }\n    cout << \"Dong nhat \" << dongNhat << \" nguoi, luc \" << gio << \" gio\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"d",ptr:["t"],label:"d[giờ]"},{type:"vars",names:["t","cur","dongNhat","gio"]}],py:{code:"# 5 khách, giờ vào và giờ ra (có mặt cả hai giờ đó), giờ từ 0 đến 11\nvao = [1, 2, 4, 6, 7]\nra = [4, 5, 6, 9, 8]\nd = [0] * 13\nfor k in range(5):\n    d[vao[k]] += 1\n    d[ra[k] + 1] -= 1\ncur = 0\ndongNhat = 0\ngio = 0\nfor t in range(12):\n    cur += d[t]\n    if cur > dongNhat:\n        dongNhat = cur\n        gio = t\nprint(\"Dong nhat\", dongNhat, \"nguoi, luc\", gio, \"gio\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        // 5 khách, giờ vào và giờ ra (có mặt cả hai giờ đó), giờ từ 0 đến 11\n        int[] vao = { 1, 2, 4, 6, 7 };\n        int[] ra = { 4, 5, 6, 9, 8 };\n        int[] d = new int[13];\n        for (int k = 0; k < 5; k++)\n        {\n            d[vao[k]]++;\n            d[ra[k] + 1]--;\n        }\n        int cur = 0, dongNhat = 0, gio = 0;\n        for (int t = 0; t < 12; t++)\n        {\n            cur += d[t];\n            if (cur > dongNhat)\n            {\n                dongNhat = cur;\n                gio = t;\n            }\n        }\n        Console.WriteLine($\"Dong nhat {dongNhat} nguoi, luc {gio} gio\");\n    }\n}"}},{label:"Ví dụ: Cộng dồn hai lần để hỏi tổng đoạn",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 6;\n    vector<long long> d(n + 1, 0), a(n, 0), pre(n + 1, 0);\n    // cộng 3 vào [0, 2], cộng 2 vào [1, 5]\n    d[0] += 3; d[3] -= 3;\n    d[1] += 2; d[6] -= 2;\n    long long cur = 0;\n    for (int i = 0; i < n; i++) {\n        cur += d[i];\n        a[i] = cur;\n        pre[i + 1] = pre[i] + a[i];\n    }\n    cout << \"Tong a[2..4] = \" << pre[5] - pre[2] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"d"},{type:"cells",of:"a",ptr:["i"]},{type:"cells",of:"pre"}],py:{code:"n = 6\nd = [0] * (n + 1)\na = [0] * n\npre = [0] * (n + 1)\n# cộng 3 vào [0, 2], cộng 2 vào [1, 5]\nd[0] += 3; d[3] -= 3\nd[1] += 2; d[6] -= 2\ncur = 0\nfor i in range(n):\n    cur += d[i]\n    a[i] = cur\n    pre[i + 1] = pre[i] + a[i]\nprint(\"Tong a[2..4] =\", pre[5] - pre[2])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 6;\n        long[] d = new long[n + 1], a = new long[n], pre = new long[n + 1];\n        // cộng 3 vào [0, 2], cộng 2 vào [1, 5]\n        d[0] += 3; d[3] -= 3;\n        d[1] += 2; d[6] -= 2;\n        long cur = 0;\n        for (int i = 0; i < n; i++)\n        {\n            cur += d[i];\n            a[i] = cur;\n            pre[i + 1] = pre[i] + a[i];\n        }\n        Console.WriteLine(\"Tong a[2..4] = \" + (pre[5] - pre[2]));\n    }\n}",note:"Hai lần cộng dồn: mảng hiệu d → giá trị a → mảng cộng dồn pre. Trong C#, nhớ đặt phép trừ trong ngoặc khi nối với chuỗi: \"…\" + (pre[5] - pre[2])."}},{label:"Lỗi: mảng hiệu thiếu một ô",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 5;\n    vector<int> d(n, 0);     // thiếu ô d[n]\n    int l = 2, r = 4, v = 7;\n    d[l] += v;\n    d[r + 1] -= v;           // r + 1 = 5: ngoài vector\n    cout << d[0] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"d",ptr:["l","r+1"]}],py:{code:"n = 5\nd = [0] * n        # thiếu ô d[n]\nl, r, v = 2, 4, 7\nd[l] += v\nd[r + 1] -= v      # r + 1 = 5: ngoài list\nprint(d[0])",note:"Khi đoạn cập nhật kết thúc ở phần tử cuối, r + 1 = n. Mảng hiệu phải có n + 1 ô. Python dừng chương trình với IndexError: list index out of range."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 5;\n        int[] d = new int[n];     // thiếu ô d[n]\n        int l = 2, r = 4, v = 7;\n        d[l] += v;\n        d[r + 1] -= v;            // r + 1 = 5: ngoài mảng\n        Console.WriteLine(d[0]);\n    }\n}",note:"Mảng hiệu cần n + 1 ô vì luôn ghi tới d[r + 1]. C# kiểm tra chỉ số nên chương trình dừng ngay với IndexOutOfRangeException (C++ thì có thể chạy tiếp và ghi đè vùng nhớ khác)."}}];
