makeEx2(document.getElementById("ex-l10"),sim10,[{t:"Cộng đoạn",d:"Đầu vào: n và q (1 ≤ n, q ≤ 10^5). Ban đầu dãy a₁..aₙ toàn số 0. Tiếp theo q dòng l r v (1 ≤ l ≤ r ≤ n, |v| ≤ 10^4): cộng v vào aₗ..aᵣ. Đầu ra: dãy a sau mọi cập nhật, các số cách nhau một khoảng trắng.",tests:[{in:"5 3\n1 3 2\n2 5 1\n4 4 -3",out:"2 3 3 -2 1"},{in:"1 2\n1 1 5\n1 1 -7",out:"-2"},{in:"4 1\n1 4 10000",out:"10000 10000 10000 10000"},{in:"6 2\n6 6 1\n1 1 1",out:"1 0 0 0 0 1"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n, q;\n    cin >> n >> q;\n    // mảng hiệu d[1..n+1]\n    return 0;\n}",perf:{gen:n=>n+" "+n+"\n"+Array.from({length:n},(_,i)=>{const l=1+(i*13)%n,r=Math.min(n,l+(n>>1));return l+" "+r+" "+((i*7)%2001-1000)}).join("\n"),ns:[500,2000,8000],need:"n",limit:n=>45*n+200,why:"Cộng vào từng ô của đoạn tốn O(n · q). Mỗi lần cập nhật chỉ cần sửa hai ô của mảng hiệu."},py:{start:"n, q = map(int, input().split())\n# mảng hiệu d[1..n+1]",hints:["Chỉ số từ 1 nên mảng hiệu cần các ô 1..n+1: d = [0] * (n + 2).","print(*a) in các phần tử cách nhau một khoảng trắng."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), q = int.Parse(t[1]);\n        // mảng hiệu d[1..n+1]\n    }\n}",hints:["Chỉ số từ 1 nên mảng hiệu cần các ô 1..n+1: tạo new long[n + 2].","Tổng các cập nhật tại một ô có thể tới 10⁹: dùng long cho an toàn.","In n số trên một dòng: gom vào StringBuilder rồi in một lần."]}},{t:"Thời điểm đông nhất",d:"Đầu vào: n (1 ≤ n ≤ 10^5) rồi n dòng a b (0 ≤ a ≤ b ≤ 10^5): một người có mặt từ thời điểm a tới thời điểm b, tính cả hai đầu. Đầu ra: số người có mặt nhiều nhất cùng lúc và thời điểm sớm nhất đạt được con số đó.",tests:[{in:"5\n1 4\n2 5\n4 6\n6 9\n7 8",out:"3 4"},{in:"1\n0 0",out:"1 0"},{in:"3\n5 5\n5 5\n5 5",out:"3 5"},{in:"2\n1 2\n3 4",out:"1 1"},{in:"2\n0 100000\n100000 100000",out:"2 100000"}],start:"#include <iostream>\nusing namespace std;\n\nint d[100002];\n\nint main() {\n    int n;\n    cin >> n;\n    // +1 ở thời điểm vào, -1 ngay sau thời điểm ra\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>{const a=(i*7919)%100000,b=Math.min(100000,a+((i*31)%5000));return a+" "+b}).join("\n"),ns:[300,1200,4800],need:"n",limit:n=>30*n+600000,why:"Với mỗi người, cộng 1 vào từng thời điểm có mặt là quá chậm khi khoảng thời gian dài. Chỉ đánh dấu hai đầu rồi quét một lần."},py:{start:"n = int(input())\nd = [0] * 100002\n# +1 ở thời điểm vào, -1 ngay sau thời điểm ra",hints:["Thời điểm tới 10⁵ và b + 1 có thể bằng 10⁵ + 1: cần 100002 ô.","Chỉ cập nhật khi cur > best (lớn hơn hẳn) để giữ thời điểm sớm nhất."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] d = new int[100002];\n        // +1 ở thời điểm vào, -1 ngay sau thời điểm ra\n    }\n}",hints:["Thời điểm tới 10⁵ và b + 1 có thể bằng 10⁵ + 1: mảng cần 100002 ô.","Chỉ cập nhật khi cur > best (lớn hơn hẳn) để giữ thời điểm sớm nhất."]}},{t:"Bật tắt đèn",d:"Đầu vào: n và q (1 ≤ n, q ≤ 10^5). Có n bóng đèn đánh số 1..n, ban đầu đều tắt. Mỗi dòng trong q dòng tiếp theo là l r: đảo trạng thái (bật thành tắt, tắt thành bật) mọi đèn từ l tới r. Đầu ra: số đèn đang bật ở cuối.",tests:[{in:"6 3\n1 4\n3 6\n2 3",out:"4"},{in:"1 2\n1 1\n1 1",out:"0"},{in:"5 1\n1 5",out:"5"},{in:"4 2\n1 2\n3 4",out:"4"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n, q;\n    cin >> n >> q;\n    // một đèn bật khi số lần bị đảo là số lẻ\n    return 0;\n}",perf:{gen:n=>n+" "+n+"\n"+Array.from({length:n},(_,i)=>{const l=1+(i*13)%n,r=Math.min(n,l+(n>>1));return l+" "+r}).join("\n"),ns:[500,2000,8000],need:"n",limit:n=>30*n+200,why:"Đảo từng đèn trong đoạn là O(n · q). Đếm số lần đảo bằng mảng hiệu chỉ cần O(n + q)."},py:{start:"n, q = map(int, input().split())\n# một đèn bật khi số lần bị đảo là số lẻ",hints:["Đèn ở cuối đang bật khi và chỉ khi nó bị đảo một số lẻ lần.","Đếm số lần bị đảo của mỗi đèn bằng mảng hiệu, rồi đếm các ô lẻ."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), q = int.Parse(t[1]);\n        // một đèn bật khi số lần bị đảo là số lẻ\n    }\n}",hints:["Đèn ở cuối đang bật khi và chỉ khi nó bị đảo một số lẻ lần.","Đếm số lần bị đảo của mỗi đèn bằng mảng hiệu, rồi đếm các ô lẻ."]}}]);

